import sys
import os
import requests

def extract_filename(url):
    parts = url.split('/')
    last_part = parts[-1]
    if '?' in last_part:
        filename = last_part.split('?')[0]
    else:
        filename = last_part
    return filename if filename else 'download'

def main():
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            response = requests.get(line)
            if response.status_code == 200:
                filename = extract_filename(line)
                filepath = os.path.join(os.getcwd(), filename)
                with open(filepath, 'wb') as f:
                    f.write(response.content)
                print(f"saved {filename} {len(response.content)}")
            else:
                print(f"failed {line} {response.status_code}")
        except requests.RequestException as e:
            print(f"failed {line} {getattr(e, 'response', None).status_code if hasattr(e, 'response') else 'unknown'}")
    sys.exit(0)

if __name__ == "__main__":
    main()

